import AppKit
import Store

public struct CapturePolicy: Sendable, Equatable {
    public static let applePasswordsBundleID = "com.apple.Passwords"

    static let concealedTypes = Set([
        "org.nspasteboard.ConcealedType",
        "com.agilebits.onepassword"
    ].map { NSPasteboard.PasteboardType($0) })

    static let transientTypes = Set([
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type"
    ].map { NSPasteboard.PasteboardType($0) })

    static let passwordManagerBundleIDs: Set<String> = [
        "com.1password.1password",
        "com.bitwarden.desktop",
        "com.apple.keychainaccess"
    ]

    public var isPaused: Bool
    public var ignoredBundleIDs: Set<String>
    public var ignoresConcealed: Bool
    public var ignoresTransient: Bool

    public init(
        isPaused: Bool = false,
        ignoredBundleIDs: Set<String> = [Self.applePasswordsBundleID],
        ignoresConcealed: Bool = true,
        ignoresTransient: Bool = true
    ) {
        self.isPaused = isPaused
        self.ignoredBundleIDs = ignoredBundleIDs
        self.ignoresConcealed = ignoresConcealed
        self.ignoresTransient = ignoresTransient
    }

    /// `frontmostBundleID` is nil when there is no frontmost app or it has no bundle id
    public func skipReason(
        types: [NSPasteboard.PasteboardType],
        frontmostBundleID: String?,
        isOwnWriteChangeCount: Bool
    ) -> SkipReason? {
        if isPaused {
            return .paused
        }
        if isOwnWriteChangeCount || types.contains(NSPasteboard.PasteboardType(PasteboardMarker.ownWrite)) {
            return .ownWrite
        }
        guard let frontmostBundleID else { return .noFrontmostApp }
        if ignoredBundleIDs.contains(frontmostBundleID) {
            return .ignoredApp
        }
        if ignoresConcealed,
           types.contains(where: Self.concealedTypes.contains) || Self.passwordManagerBundleIDs
           .contains(frontmostBundleID)
        {
            return .concealed
        }
        if ignoresTransient, types.contains(where: Self.transientTypes.contains) {
            return .transient
        }
        return nil
    }
}
